const projects=window.DEMO_PROJECTS;const app=document.querySelector('#app');let view='dashboard',selected=null,mode='map',filters={ward:'',department:'',status:'',year:''},pending=[],approved=[],photoUrls=[];const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const short=d=>new Date(d+'T12:00:00').toLocaleDateString('en-KE',{day:'numeric',month:'short',year:'numeric'});const cls=s=>s==='On track'?'ontrack':s.toLowerCase();const pill=s=>`<span class="pill ${cls(s)}">${esc(s)}</span>`;const list=()=>projects.filter(p=>(!filters.ward||p.ward===filters.ward)&&(!filters.department||p.department===filters.department)&&(!filters.status||p.status===filters.status)&&(!filters.year||p.year===filters.year));const overdue=p=>(Date.parse('2026-09-28')-Date.parse(p.updated))/86400000>14;function nav(v,id){view=v;selected=id||null;render();window.scrollTo({top:0,behavior:'smooth'});app.focus({preventScroll:true})}window.openProject=id=>nav('detail',id);const unique=k=>[...new Set(projects.map(p=>p[k]))].sort();function filtersHtml(publicOnly=false){let keys=publicOnly?['ward']:['ward','department','status','year'];return `<div class="filters">${keys.map(k=>`<label>${({ward:'Ward',department:'Department',status:'Status',year:'Financial year'})[k]}<select data-filter="${k}"><option value="">All ${k==='year'?'years':k==='status'?'statuses':k+'s'}</option>${unique(k).map(v=>`<option value="${esc(v)}" ${filters[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`).join('')}</div>`}function card(p,publicOnly=false){return `<button class="projectcard" data-project="${p.id}">${pill(p.status)}<h3>${esc(p.name)}</h3><p>${esc(p.ward)} · ${esc(p.department)}</p><div class="progress" aria-label="Illustrative progress ${p.progress}%"><b style="width:${p.progress}%"></b></div><div class="cardbottom"><span>${p.progress}% illustrative progress</span><span>View details →</span></div></button>`}function mapHtml(tall=false){return `<div id="map" class="map ${tall?'tall':''}" role="region" aria-label="Map of illustrative project localities"></div><div class="legend" aria-label="Map legend"><span><b class="marker-symbol ontrack">●</b> On track</span><span><b class="marker-symbol delayed">!</b> Delayed</span><span><b class="marker-symbol completed">✓</b> Completed</span></div><p class="muted" style="font-size:12px">Pins indicate checked localities, not verified project sites. Projects without coordinates appear in the list only.</p>`}let mapRef;function drawMap(){let el=document.getElementById('map');if(!el)return;if(!window.L){el.innerHTML='<div class="mapfallback">Map tiles are unavailable offline. Use the project list to open every record.</div>';return}mapRef=L.map(el,{scrollWheelZoom:false}).setView([-1.08,35.65],9);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors',maxZoom:18}).addTo(mapRef);let markers=[];for(let p of list().filter(x=>x.lat!=null&&x.lng!=null)){let icon=L.divIcon({className:'',html:`<div class="pin ${cls(p.status)}" aria-label="${esc(p.status)}">${p.status==='Delayed'?'!':p.status==='Completed'?'✓':'●'}</div>`,iconSize:[30,30],iconAnchor:[15,15]});let m=L.marker([p.lat,p.lng],{icon,title:p.name}).addTo(mapRef);let content=document.createElement('div');content.innerHTML=`<strong>${esc(p.name)}</strong><br>${esc(p.ward)} · ${esc(p.status)}<br>Updated ${short(p.updated)}<br><button type="button">View details →</button>`;content.querySelector('button').onclick=()=>openProject(p.id);m.bindPopup(content);markers.push(m);if(selected===p.id)m.openPopup()}if(markers.length&&filters.ward)mapRef.fitBounds(L.featureGroup(markers).getBounds().pad(.3),{maxZoom:12});setTimeout(()=>mapRef.invalidateSize(),100)}function dashboard(){let a=list(),counts={total:a.length,track:a.filter(p=>p.status==='On track').length,delayed:a.filter(p=>p.status==='Delayed').length,done:a.filter(p=>p.status==='Completed').length,overdue:a.filter(overdue).length};let needs=a.filter(p=>p.status==='Delayed'||overdue(p)).sort((x,y)=>Number(y.status==='Delayed')-Number(x.status==='Delayed'));return `<div class="heading"><div><p class="eyebrow">Executive overview · illustrative demo</p><h1>Project oversight</h1><p class="subhead">A clear view of delivery across Narok wards</p></div><button class="btn" data-view="updates">＋ Field update</button></div>${filtersHtml()}<div class="stats"><div class="stat"><span>Total projects</span><strong>${counts.total}</strong><small>Matching filters</small></div><div class="stat good"><span>On track</span><strong>${counts.track}</strong><small>Progressing as planned</small></div><div class="stat alert"><span>Delayed</span><strong>${counts.delayed}</strong><small>Require follow-up</small></div><div class="stat"><span>Completed</span><strong>${counts.done}</strong><small>Illustrative handovers</small></div><div class="stat alert"><span>Overdue updates</span><strong>${counts.overdue}</strong><small>More than 14 days since update</small></div></div><div class="grid"><section class="panel"><div class="panelhead"><h2>Needs attention</h2><span class="muted">${needs.length} projects</span></div>${needs.length?`<div class="attention">${needs.map(p=>`<button data-project="${p.id}"><div><strong>${esc(p.name)}</strong><p>${esc(p.status==='Delayed'?p.blocker:'Field update overdue — last report '+short(p.updated))}</p></div><span aria-hidden="true">→</span></button>`).join('')}</div>`:'<div class="empty">No projects need attention in this selection.</div>'}</section><section class="panel"><div class="panelhead"><h2>County project map</h2><button class="linkbtn" data-view="explore">Explore map →</button></div>${mapHtml()}</section></div><section class="section"><div class="panelhead"><h2>Projects</h2><button class="linkbtn" data-view="explore">View all →</button></div>${a.length?`<div class="projectlist">${a.map(p=>card(p)).join('')}</div>`:'<div class="empty">No projects match these filters. Try another ward, department, status or year.</div>'}</section>`}function explore(){let a=list();return `<div class="heading"><div><p class="eyebrow">Geographic view · illustrative demo</p><h1>Explore projects</h1><p class="subhead">${a.length} matching projects across Narok wards</p></div><div class="switch" aria-label="Map or list view"><button data-mode="map" class="${mode==='map'?'active':''}" aria-pressed="${mode==='map'}">Map</button><button data-mode="list" class="${mode==='list'?'active':''}" aria-pressed="${mode==='list'}">List</button></div></div>${filtersHtml()}${mode==='map'?`<section class="panel">${mapHtml(true)}</section><section class="section"><div class="panelhead"><h2>Project list</h2><span class="muted">${a.length} results</span></div>${a.length?`<div class="projectlist">${a.map(p=>card(p)).join('')}</div>`:'<div class="empty">No projects match these filters. Change a filter to see more.</div>'}</section>`:`${a.length?`<div class="projectlist">${a.map(p=>card(p)).join('')}</div>`:'<div class="empty">No projects match these filters. Change a filter to see more.</div>'}`}`}
function detail(p,publicOnly=false){let upd=[...p.updates,...approved.filter(u=>u.projectId===p.id).map(u=>({date:u.date,note:u.note,approved:true,photo:u.photo}))].sort((a,b)=>b.date.localeCompare(a.date));return `<button class="linkbtn back" data-view="${publicOnly?'public':'explore'}">← Back to ${publicOnly?'public projects':'projects'}</button><div class="heading"><div><p class="eyebrow">${esc(p.id)} · ${publicOnly?'Public project record':'Project record'} · illustrative demo</p><h1>${esc(p.name)}</h1><p class="subhead">${esc(p.ward)} · ${esc(p.place)}</p></div>${pill(p.status)}</div><div class="detailgrid"><div><section class="panel"><div class="panelhead"><h2>Project overview</h2><span class="muted">${p.progress}% illustrative</span></div><div class="progress"><b style="width:${p.progress}%"></b></div><dl class="info"><div><dt>Ward</dt><dd>${esc(p.ward)}</dd></div><div><dt>Locality</dt><dd>${esc(p.place)}</dd></div><div><dt>Department</dt><dd>${esc(p.department)}</dd></div><div><dt>Financial year</dt><dd>${esc(p.year)}</dd></div><div><dt>Planned start</dt><dd>${short(p.start)}</dd></div><div><dt>Planned finish</dt><dd>${short(p.end)}</dd></div>${publicOnly?'':`<div><dt>Responsible officer</dt><dd>${esc(p.officer)} (demo initials)</dd></div><div><dt>Illustrative budget</dt><dd>${esc(p.budget)}</dd></div>`}</dl></section><section class="panel section"><h2>Milestones</h2>${p.milestones.map(([n,v])=>`<div class="milestone"><span>${esc(n)}</span><b>${v}% demo</b></div>`).join('')}</section><section class="panel section"><h2>${publicOnly?'Approved updates':'Field update timeline'}</h2><p class="muted">All dates and notes below are illustrative.</p><div class="timeline">${upd.map(u=>`<div class="event"><small>${short(u.date)} · Approved for public view</small><p>${esc(u.note)}</p>${u.photo?`<img src="${u.photo}" alt="Illustrative field update attachment" style="max-width:100%;max-height:220px;border-radius:8px">`:'<div class="photo">No site photo attached · illustrative record</div>'}</div>`).join('')}</div>${!publicOnly&&pending.some(u=>u.projectId===p.id)?`<div class="pending"><strong>Awaiting review</strong><p>${pending.filter(u=>u.projectId===p.id).length} local update(s) have not been approved for public view.</p></div>`:''}</section></div><div><section class="panel"><h2>Location</h2><div class="section">${p.lat!=null?`<div id="map" class="map" role="region" aria-label="Location near ${esc(p.place)}"></div><p class="muted">Near ${esc(p.place)} · ${p.lat.toFixed(5)}, ${p.lng.toFixed(5)}</p><p class="muted" style="font-size:13px">Locality coordinates only; exact project site not verified.</p><a class="btn secondary" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination=${p.lat},${p.lng}">Open directions ↗</a>`:'<div class="empty">Location not yet verified</div>'}</div></section>${publicOnly?'':`<section class="panel section"><h2>Management follow-up</h2><div class="callout section"><strong>Current blocker</strong><p>${esc(p.blocker)}</p><strong>Next action</strong><p>${esc(p.next)}</p><strong>Action owner</strong><p>${esc(p.owner)}</p></div><p class="muted">Last field update: ${short(p.updated)}</p><button class="btn" data-update-project="${p.id}">Submit field update</button></section><section class="panel section"><h2>Internal management note</h2><p>${esc(p.internal)}</p><p class="muted" style="font-size:13px">Hidden from the public view.</p></section>`}</div></div>`}
function updates(){return `<div class="heading"><div><p class="eyebrow">Officer workspace · illustrative demo</p><h1>Submit field update</h1><p class="subhead">Record progress for management review</p></div></div><div class="notice">Submissions are kept only in this open browser session. They are not shared with the county. An update appears in the public view only after you approve it here for this demo.</div><div class="splitview section"><section class="panel"><form id="updateForm" class="form" novalidate><label class="field">Project <select name="projectId" required><option value="">Choose a project</option>${projects.map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.name)} · ${esc(p.ward)}</option>`).join('')}</select></label><div class="formrow"><label class="field">Milestone <select name="milestone" required><option value="">Choose a milestone</option></select></label><label class="field">Progress (%) <input name="progress" type="number" min="0" max="100" inputmode="numeric" placeholder="0–100" required></label></div><label class="field">Site note <textarea name="note" minlength="8" maxlength="500" placeholder="What changed at the site?" required></textarea><small>8–500 characters. Keep personal details out of public notes.</small></label><label class="field">Blocker (optional) <textarea name="blocker" maxlength="300" placeholder="What is preventing the next step?"></textarea></label><label class="field">Site photo (optional) <input name="photo" type="file" accept="image/*"><small>Image only, up to 3 MB. Kept in this browser session.</small></label><div id="formMessage" role="status" aria-live="polite"></div><button class="btn" type="submit">Submit for review →</button></form></section><section class="panel"><div class="panelhead"><h2>Review queue</h2><span class="muted">${pending.length} awaiting approval</span></div>${pending.length?pending.map(u=>`<div class="pending"><strong>${esc(projects.find(p=>p.id===u.projectId)?.name)}</strong><p>${esc(u.milestone)} · ${u.progress}% · ${esc(u.note)}</p>${u.blocker?`<p><strong>Blocker:</strong> ${esc(u.blocker)}</p>`:''}<small>Submitted ${short(u.date)} · local demo only</small><div><button class="btn" data-approve="${u.id}">Approve for public demo</button></div></div>`).join(''):'<div class="empty">No updates awaiting review. Submit one using the form.</div>'}${approved.length?`<h3 class="section">Approved in this session</h3>${approved.map(u=>`<p class="notice">${esc(projects.find(p=>p.id===u.projectId)?.name)} · ${esc(u.milestone)} · ${u.progress}%</p>`).join('')}`:''}</section></div>`}function publicPage(){let a=projects.filter(p=>!filters.ward||p.ward===filters.ward);return `<div class="publicbanner"><p class="eyebrow" style="color:#e4b95d">Resident view · illustrative demo</p><h1>Projects in your ward</h1><p>Browse sample projects and approved updates. These records do not represent verified county work.</p></div>${filtersHtml(true)}<div class="panelhead"><h2>Approved project information</h2><span class="muted">${a.length} sample projects</span></div>${a.length?`<div class="projectlist">${a.map(p=>card(p,true)).join('')}</div>`:'<div class="empty">No sample projects in this ward.</div>'}`}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(mapRef){mapRef.remove();mapRef=null}app.innerHTML=view==='dashboard'?dashboard():view==='explore'?explore():view==='updates'?updates():view==='public'?publicPage():detail(projects.find(p=>p.id===selected)||projects[0],view==='publicdetail');if(view==='detail'&&selected){let p=projects.find(p=>p.id===selected);if(p?.lat!=null)drawDetailMap(p)}else if(view==='publicdetail'){let p=projects.find(p=>p.id===selected);if(p?.lat!=null)drawDetailMap(p)}else drawMap();if(view==='updates')populateMilestones()}function drawDetailMap(p){let el=document.getElementById('map');if(!el)return;if(!window.L){el.innerHTML='<div class="mapfallback">Map unavailable offline. Coordinates are listed below.</div>';return}mapRef=L.map(el,{scrollWheelZoom:false}).setView([p.lat,p.lng],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(mapRef);L.marker([p.lat,p.lng],{title:p.place}).addTo(mapRef).bindPopup('Approximate locality · illustrative demo').openPopup();setTimeout(()=>mapRef.invalidateSize(),100)}function populateMilestones(){let select=document.querySelector('[name=projectId]'),milestone=document.querySelector('[name=milestone]');if(!select||!milestone)return;let p=projects.find(x=>x.id===select.value);milestone.innerHTML='<option value="">Choose a milestone</option>'+(p?.milestones||[]).map(([n])=>`<option value="${esc(n)}">${esc(n)}</option>`).join('')}document.addEventListener('click',e=>{let b=e.target.closest('[data-view],[data-project],[data-mode],[data-approve],[data-update-project]');if(!b)return;if(b.dataset.project){selected=b.dataset.project;nav(view==='public'?'publicdetail':'detail',selected)}else if(b.dataset.updateProject){nav('updates',b.dataset.updateProject)}else if(b.dataset.view)nav(b.dataset.view);else if(b.dataset.mode){mode=b.dataset.mode;render()}else if(b.dataset.approve){let i=pending.findIndex(u=>u.id===b.dataset.approve);if(i>=0){approved.unshift(...pending.splice(i,1));render();app.querySelector('.notice')?.scrollIntoView({block:'nearest'})}}});document.addEventListener('change',e=>{if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;render()}if(e.target.name==='projectId')populateMilestones()});document.addEventListener('submit',async e=>{if(e.target.id!=='updateForm')return;e.preventDefault();let form=e.target,msg=document.querySelector('#formMessage');msg.innerHTML='';if(!form.checkValidity()){form.reportValidity();msg.innerHTML='<p class="error">Please complete the required fields and keep progress between 0 and 100.</p>';return}let fd=new FormData(form),file=fd.get('photo');if(file?.size>3*1024*1024||file?.size&&!file.type.startsWith('image/')){msg.innerHTML='<p class="error">Choose an image smaller than 3 MB.</p>';return}let btn=form.querySelector('[type=submit]');btn.disabled=true;btn.textContent='Saving locally…';try{let photo=file?.size?URL.createObjectURL(file):null;if(photo)photoUrls.push(photo);let u={id:String(Date.now()),projectId:fd.get('projectId'),milestone:fd.get('milestone'),progress:Number(fd.get('progress')),note:String(fd.get('note')).trim(),blocker:String(fd.get('blocker')).trim(),photo,date:new Date().toISOString().slice(0,10)};if(u.note.length<8)throw Error('Write at least 8 characters in the site note.');pending.unshift(u);render();document.querySelector('#formMessage').innerHTML='<div class="success">Update saved locally and awaiting review. Approve it in the review queue to show it in the public demo.</div>'}catch(err){btn.disabled=false;btn.textContent='Submit for review →';msg.innerHTML=`<p class="error">${esc(err.message||'Unable to save this update.')}</p>`}});render();
